{
  "findings": [
    {
      "check_id": "CKV_AWS_355",
      "title": "Ensure no IAM policies documents allow '*' as a statement's resource for restrictable actions",
      "resource": "aws_iam_policy.privesc-ssmStartSession-policy",
      "severity": "MEDIUM",
      "explanation": "The policy allows unrestricted access ('*') to all resources for sensitive actions like 'ssm:StartSession' and 'ec2:DescribeInstances'. This can lead to privilege escalation or unauthorized access."
    },
    {
      "check_id": "CKV_AWS_290",
      "title": "Ensure IAM policies do not allow write access without constraints",
      "resource": "aws_iam_policy.privesc-ssmStartSession-policy",
      "severity": "MEDIUM",
      "explanation": "The policy allows actions like 'ssm:TerminateSession' and 'ssm:ResumeSession' without resource constraints. This can lead to unauthorized session manipulation."
    }
  ],
  "patched_code": "resource "aws_iam_policy" "privesc-ssmStartSession-policy" {
  name        = "privesc-ssmStartSession-policy"
  path        = "/"
  description = "Allows privesc via targeted ssm"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ssm:StartSession",
          "ssm:DescribeSessions",
          "ssm:GetConnectionStatus",
          "ssm:DescribeInstanceProperties",
          "ssm:TerminateSession",
          "ssm:ResumeSession"
        ]
        Resource = [
          "arn:aws:ec2:*:*:instance/*",
          "arn:aws:ssm:*:*:session/*"
        ]
      },
    ]
  })
}",
  "fix_summary": "Restricted the 'Resource' field to specific ARNs for EC2 instances and SSM sessions, removing the wildcard ('*') to mitigate unrestricted access risks."
}
